// 监听文件改动
function fileWatcher(path) {
    const hasFile = fs.existsSync(path);
    console.log('hasFile', hasFile, "路径", path);
    if (!hasFile) {
        fs.writeFileSync(path, '');
    }
    exports.g_fileWatcher = fs.watch(path, (eventType, filename) => {
        if (eventType === 'change') {
            const isHuawei = vscode.workspace
                .getConfiguration()
                .get('syslab.isHuawei');
            const content = JSON.parse(fs.readFileSync(path).toString());
            if (isHuawei && g_userid !== content.userId) {
                return;
            }
            // if(g_setting.figId !== content.figId){
            //   g_setting.figId = content.figId;
            //   showStaticImg(content.figId);
            // }
            // 判断
            console.log('fig.json文件改动，看看内容', content);
            if (exports.g_applyMode === 'app') {
                showApp(content.figId, content.title, content.fignum, content.backend);
                return;
            }
            showStaticImg(content.figId, content.title, content.fignum, content.backend);
        }
    });
}
async function showParallelismPlot(figData) {
    console.log('figData', figData);
    let figId = figData.figId;
    let title = figData.title;
    let png_base64 = figData.png_base64;
    let figPklPath = figData.figPklPath;
    const paramData = new FormData();
    paramData.append('figId', figId);
    paramData.append('png', png_base64);
    postHttp(`/savePngBase64`, paramData)
        .then((res) => {
        showStaticImg(figId, title, "0", "python", figPklPath);
    })
        .catch((err) => {
        console.log(`静态绘图异常:请检查绘图代码并重新绘图`, err);
        // vscode.window.showWarningMessage(
        //   `静态绘图异常:请检查绘图代码并重新绘图。${err}`
        // );
    });
}
