// 导入fig
async function export_figure(figId, file_type_name, file_type, export_api) {
    let defaultPath = vscode.workspace.workspaceFolders
        ? vscode.workspace.workspaceFolders[0]?.uri.fsPath
        : undefined;
    //console.log(vscode.workspace.workspaceFolders, defaultPath);
    if (defaultPath) {
        defaultPath = path.join(defaultPath, `${exports.active_figure.WebviewPanel.title}.${file_type}`);
    }
    else {
        defaultPath = path.join(process.env.USER_DATA_DIR || os.homedir(), `${exports.active_figure.WebviewPanel.title}.${file_type}`);
    }
    const result = await vscode.window.showSaveDialog({
        saveLabel: '保存',
        title: `保存为${file_type_name}`,
        defaultUri: vscode.Uri.file(defaultPath),
        filters: {
            [file_type]: [file_type],
        },
    });
    if (result) {
        vscode.window.withProgress({
            location: vscode.ProgressLocation.Notification,
            title: '',
            cancellable: false,
        }, (progress, token) => {
            const p = new Promise((resolve) => {
                g_progress = {
                    progress: progress,
                    resolve: resolve,
                };
                progress.report({
                    message: `正在导出${file_type_name}文件到` + result.fsPath,
                });
                const option = {
                    hostname: 'localhost',
                    port: webagg_port,
                    path: export_api,
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                };
                const req = http.request(option, (res) => {
                    res.on('data', (data) => {
                        const res = JSON.parse(data.toString());
                        if (res.status) {
                            vscode.window.showInformationMessage(`导出${file_type_name}文件成功` + result.fsPath);
                        }
                        else {
                            vscode.window.showErrorMessage(`导出${file_type_name}文件失败` + result.fsPath);
                        }
                        clearProgress();
                    });
                });
                req.on('error', (err) => {
                    vscode.window.showErrorMessage(`导出${file_type_name}文件失败` + result.fsPath);
                    clearProgress();
                });
                req.on('timeout', () => {
                    vscode.window.showErrorMessage(`导出${file_type_name}文件失败` + result.fsPath);
                    clearProgress();
                });
                const data = {
                    figId,
                    filename: result.fsPath,
                };
                req.write(JSON.stringify(data));
                req.end();
            });
            return p;
        });
    }
}
